package com.brainserve.onboarding.forms.domain.model;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="form_submissions",schema="client_onboarding")
public class FormSubmission {
 @Id private UUID id; @Column(name="organization_id",nullable=false) private UUID organizationId; @Column(name="onboarding_id",nullable=false) private UUID onboardingId; @Column(name="step_instance_id",nullable=false) private UUID stepInstanceId; @Column(name="project_id",nullable=false) private UUID projectId; @Column(name="client_user_id",nullable=false) private UUID clientUserId; @Column(name="form_version_id",nullable=false) private UUID formVersionId; @Column(name="submission_number",nullable=false) private int submissionNumber; @Column(name="previous_submission_id") private UUID previousSubmissionId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=32) private FormSubmissionStatus status; @Column(name="submitted_at") private Instant submittedAt; @Column(name="review_started_at") private Instant reviewStartedAt; @Column(name="reviewed_at") private Instant reviewedAt; @Column(name="reviewer_user_id") private UUID reviewerUserId; @Column(name="revision_note",length=2000) private String revisionNote; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="created_by",nullable=false) private UUID createdBy; @Column(name="updated_at",nullable=false) private Instant updatedAt; @Column(name="updated_by",nullable=false) private UUID updatedBy; @Version private long version;
 protected FormSubmission(){} public FormSubmission(UUID id,UUID org,UUID onboardingId,UUID stepId,UUID projectId,UUID clientUserId,UUID formVersionId,int number,UUID previous,UUID actor,Instant now){this.id=id;organizationId=org;this.onboardingId=onboardingId;stepInstanceId=stepId;this.projectId=projectId;this.clientUserId=clientUserId;this.formVersionId=formVersionId;submissionNumber=number;previousSubmissionId=previous;status=FormSubmissionStatus.DRAFT;createdAt=now;createdBy=actor;updatedAt=now;updatedBy=actor;}
 public void touch(UUID actor,Instant now){requireDraft();updatedBy=actor;updatedAt=now;} public void submit(UUID actor,Instant now){requireDraft();status=FormSubmissionStatus.SUBMITTED;submittedAt=now;updatedBy=actor;updatedAt=now;} public void startReview(UUID reviewer,Instant now){if(status!=FormSubmissionStatus.SUBMITTED)throw new IllegalStateException("Only submitted forms can enter review");status=FormSubmissionStatus.UNDER_REVIEW;reviewStartedAt=now;reviewerUserId=reviewer;updatedBy=reviewer;updatedAt=now;} public void requestRevision(UUID reviewer,String note,Instant now){if(status!=FormSubmissionStatus.UNDER_REVIEW)throw new IllegalStateException("Only forms under review can be returned for revision");markRevision(reviewer,note,now);} public void requestFinalReviewRevision(UUID reviewer,String note,Instant now){if(status!=FormSubmissionStatus.APPROVED)throw new IllegalStateException("Only approved forms can be reopened from final review");markRevision(reviewer,note,now);} private void markRevision(UUID reviewer,String note,Instant now){revisionNote=FormTemplate.text(note,"Revision reason",2000);status=FormSubmissionStatus.NEEDS_REVISION;reviewedAt=now;reviewerUserId=reviewer;updatedBy=reviewer;updatedAt=now;} public void approve(UUID reviewer,Instant now){if(status!=FormSubmissionStatus.UNDER_REVIEW&&status!=FormSubmissionStatus.SUBMITTED)throw new IllegalStateException("Only submitted forms can be approved");if(reviewStartedAt==null)reviewStartedAt=now;status=FormSubmissionStatus.APPROVED;reviewedAt=now;reviewerUserId=reviewer;updatedBy=reviewer;updatedAt=now;} public void autoApprove(UUID actor,Instant now){if(status!=FormSubmissionStatus.SUBMITTED)throw new IllegalStateException("Only submitted forms can be auto-approved");status=FormSubmissionStatus.APPROVED;reviewedAt=now;updatedBy=actor;updatedAt=now;} private void requireDraft(){if(status!=FormSubmissionStatus.DRAFT)throw new IllegalStateException("Submitted form versions are immutable");}
 public UUID getId(){return id;} public UUID getOrganizationId(){return organizationId;} public UUID getOnboardingId(){return onboardingId;} public UUID getStepInstanceId(){return stepInstanceId;} public UUID getProjectId(){return projectId;} public UUID getClientUserId(){return clientUserId;} public UUID getFormVersionId(){return formVersionId;} public int getSubmissionNumber(){return submissionNumber;} public UUID getPreviousSubmissionId(){return previousSubmissionId;} public FormSubmissionStatus getStatus(){return status;} public Instant getSubmittedAt(){return submittedAt;} public Instant getReviewStartedAt(){return reviewStartedAt;} public Instant getReviewedAt(){return reviewedAt;} public UUID getReviewerUserId(){return reviewerUserId;} public String getRevisionNote(){return revisionNote;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} public long getVersion(){return version;}
}
